45],408304,6,109,388,"「花火に連れてきてくださり、ありがとうございます。\n貴方に会うと、いつも子供の頃を……友人と当たり前のように会えていた頃を思い出します。\n『心寄せる者とは何度でも会うことです。共に過ごす時間が、互いにとって最上の贈り物になりますから』\nこれは、かつてシスターが私たちに授けてくれた教えです。\n貴方と会えること、その一回一回を、私はとても大切にしています。\nそして……叶うなら、これからも、貴方ともっとたくさんの花火が見たいと思っています。」",200083,2,"deco/character/yifu_cj",false,false,1,false,false,false,false,"1",1,3672,5000,1737,2652,3000,11166,12566,8566,12500,8000,3000,"yifu_cj"},h)g[408401]=b({e[46057],408401,false,166,389,false,200084,false,"deco/character/linlang",302002,60,false,false,false,false,120,"1",false,false,false,false,false,false,"-60,0,1","110,-300,1.06",false,"-100,0,1",false,false,false,"-100,40,0.95","-100,40,0.95",false,false,"-20,60,1",1958,973,390,1046,832,1905,2007,1046,832,1905,1096,"linlang"},h)